import { execFileSync } from 'node:child_process'
import { rmSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

import { frontendFeatures } from './module-collections.ts'

const config = new URL('../tsconfig.check.json', import.meta.url)

writeFileSync(
  config,
  '// Generated by scripts/check-types.ts. Do not edit.\n' +
    JSON.stringify(
      {
        extends: './tsconfig.json',
        include: [
          '**/*.ts',
          '**/*.tsx',
          '../../modules/*/**/*.ts',
          '../../modules/*/**/*.tsx',
          '../../modules/*/**/*.ts',
          '../../modules/*/**/*.tsx',
          ...frontendFeatures.active.flatMap((feature) => [
            `../../${feature.path}/**/*.ts`,
            `../../${feature.path}/**/*.tsx`,
          ]),
        ],
      },
      null,
      2,
    ),
)

try {
  execFileSync('pnpm', ['exec', 'tsc', '--noEmit', '--project', fileURLToPath(config)], {
    stdio: 'inherit',
    cwd: fileURLToPath(new URL('../', import.meta.url)),
  })
} finally {
  rmSync(config)
}
